1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
3	const CURSE_SURCHARGE_RATE = 0.5;
4	const COMPONENT_BASE = 25;
5	const COMPONENT_BLOCK_BASE = 60;
6	const COMPONENT_BLOCK_SIZE = 3;
7	
8	const BASE_PREMIUM: Record<string, number> = {
9	  sword: 100,
10	  amulet: 60,
11	  staff: 80,
12	  potion: 40,
13	};
14	
15	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
16	
17	type Item = { type: string; cursed?: boolean };
18	type Step = { op: "quote"; items: Item[] };
19	type Scenario = { customer: { yearsWithMHPCO: number }; steps: Step[] };
20	
21	const basePremiumForComponentCount = (count: number): number =>
22	  count === COMPONENT_BLOCK_SIZE ? COMPONENT_BLOCK_BASE : count * COMPONENT_BASE;
23	
24	const basePremiumForItem = (item: Item): number =>
25	  COMPONENT_TYPES.has(item.type) ? COMPONENT_BASE : BASE_PREMIUM[item.type];
26	
27	const countByType = (items: Item[]): Map<string, number> =>
28	  items.reduce(
29	    (counts, { type }) => counts.set(type, (counts.get(type) ?? 0) + 1),
30	    new Map<string, number>(),
31	  );
32	
33	const basePremiumForItemGroup = (type: string, count: number): number =>
34	  COMPONENT_TYPES.has(type) ? basePremiumForComponentCount(count) : count * BASE_PREMIUM[type];
35	
36	const basePremiumForItems = (items: Item[]): number =>
37	  [...countByType(items)].reduce(
38	    (sum, [type, count]) => sum + basePremiumForItemGroup(type, count),
39	    0,
40	  );
41	
42	const itemSurcharges = (items: Item[]): number =>
43	  items.reduce(
44	    (sum, item) => sum + (item.cursed ? basePremiumForItem(item) * CURSE_SURCHARGE_RATE : 0),
45	    0,
46	  );
47	
48	const roundInMHPCOsFavor = (premium: number): number => Math.ceil(premium);
49	
50	const withFirstInsuranceSurcharge = (base: number): number =>
51	  base + base * FIRST_INSURANCE_SURCHARGE_RATE;
52	
53	const quotePremium = (step: Step): number =>
54	  roundInMHPCOsFavor(
55	    withFirstInsuranceSurcharge(basePremiumForItems(step.items)) + itemSurcharges(step.items),
56	  ) + PROCESSING_FEE;
57	
58	export const runScenario = (scenario: Scenario): { results: Array<{ premium: number }> } => ({
59	  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
60	});
